I'll help you implement the parent-child project hierarchy with collapsible sections and smart search. Let me break down the requirements and update the necessary components.

## Architecture Overview

**Key Changes:**
1. **ProjectCard** → Support parent expansion state with child count badge
2. **ProjectList** → Manage expanded/collapsed state; expand all on search
3. **Data Structure** → Flatten parent-child relationships for display with hierarchy tracking

---

## Updated Components

```vue src/components/ProjectCard.vue
<script setup>
import moment from 'moment'
</script>

<template>
  <div class="border-b border-base-300">
    <!-- Parent/Item Row -->
    <button
      @click="handleRowClick"
      class="w-full text-left px-4 py-3 hover:bg-base-300/50 transition-colors active:bg-base-300 flex items-center justify-between gap-3 group"
      :class="{ 'bg-primary/10 border-l-4 border-l-primary': isCurrent }"
    >
      <!-- Left Content: Icon + Project Info -->
      <div class="flex items-center gap-3 flex-1 min-w-0">
        <!-- Expand/Collapse Toggle (only for parents with children) -->
        <div v-if="hasChildren" class="flex-shrink-0 w-6 flex justify-center">
          <button
            @click.stop="toggleExpand"
            class="btn btn-ghost btn-xs btn-circle transition-transform"
            :class="{ 'rotate-90': isExpanded }"
          >
            <i class="fa-solid fa-chevron-right text-xs"></i>
          </button>
        </div>
        <div v-else class="w-6"></div>

        <!-- Project Icon -->
        <div class="flex-shrink-0 w-10 h-10 rounded-lg overflow-hidden bg-base-200 border border-base-300">
          <img
            :src="project.project_icon"
            :alt="project.project_name"
            class="w-full h-full object-cover"
          />
        </div>

        <!-- Project Metadata -->
        <div class="flex-1 min-w-0">
          <!-- Project Name + Current Badge + Child Count -->
          <div class="flex items-center gap-2 mb-1">
            <h3 class="font-bold text-sm truncate group-hover:text-primary transition-colors">
              {{ project.project_name }}
            </h3>
            <span v-if="isCurrent" class="badge badge-primary badge-xs flex-shrink-0">
              Active
            </span>
            <span v-if="hasChildren" class="badge badge-ghost badge-xs flex-shrink-0">
              {{ project.childProjects?.length || 0 }}
            </span>
          </div>

          <!-- Path + Parent Info -->
          <p class="text-xs text-base-content/60 truncate mb-1 tooltip tooltip-bottom"
            :data-tip="project.abs_project_path">
            {{ project.abs_project_path }}
          </p>

          <!-- Metadata Row: Last Access -->
          <div class="flex items-center gap-2 text-xs text-base-content/50">
            <span v-if="lastAccessText" class="flex items-center gap-1">
              <i class="fa-solid fa-clock text-xs"></i>
              <span>{{ lastAccessText }}</span>
            </span>
          </div>
        </div>
      </div>

      <!-- Right Actions: Open Folder -->
      <div class="flex items-center gap-2 flex-shrink-0">
        <button
          @click.stop="$emit('open-folder')"
          class="btn btn-ghost btn-sm btn-circle opacity-0 group-hover:opacity-100 transition-opacity"
          title="Open in file explorer"
        >
          <i class="fa-regular fa-folder-open"></i>
        </button>
      </div>
    </button>

    <!-- Children (if expanded) -->
    <div v-if="isExpanded && hasChildren" class="bg-base-200/30 border-l-2 border-base-300">
      <div
        v-for="child in project.childProjects"
        :key="child.project_name"
        class="px-4 py-2 text-left hover:bg-base-300/30 transition-colors flex items-center gap-3 group"
      >
        <!-- Child Indent Marker -->
        <div class="flex-shrink-0 w-6 flex justify-center">
          <div class="w-0.5 h-4 bg-base-300"></div>
        </div>

        <!-- Child Icon -->
        <div class="flex-shrink-0 w-8 h-8 rounded-lg overflow-hidden bg-base-200 border border-base-300">
          <img
            :src="child.project_icon"
            :alt="child.project_name"
            class="w-full h-full object-cover"
          />
        </div>

        <!-- Child Info -->
        <div class="flex-1 min-w-0">
          <div class="flex items-center gap-2 mb-0.5">
            <h4 class="font-semibold text-xs truncate group-hover:text-primary transition-colors">
              {{ child.project_name }}
            </h4>
            <span v-if="child.project_name === currentProject?.project_name" class="badge badge-primary badge-xs flex-shrink-0">
              Active
            </span>
          </div>
          <p class="text-xs text-base-content/50 truncate">
            {{ child.abs_project_path }}
          </p>
        </div>

        <!-- Child Actions -->
        <button
          @click.stop="$emit('select', child)"
          class="btn btn-ghost btn-xs gap-1 opacity-0 group-hover:opacity-100 transition-opacity flex-shrink-0"
        >
          <i class="fa-solid fa-arrow-right text-xs"></i>
        </button>
      </div>
    </div>
  </div>
</template>

<script>
export default {
  props: {
    project: {
      type: Object,
      required: true
    },
    isCurrent: {
      type: Boolean,
      default: false
    },
    isExpanded: {
      type: Boolean,
      default: false
    },
    currentProject: {
      type: Object,
      default: null
    }
  },
  emits: ['select', 'open-folder', 'toggle-expand'],
  computed: {
    hasChildren() {
      return this.project.childProjects && this.project.childProjects.length > 0
    },
    lastAccessText() {
      if (!this.project?.last_access_time) return null
      try {
        return moment(this.project.last_access_time).fromNow()
      } catch {
        return null
      }
    }
  },
  methods: {
    handleRowClick() {
      this.$emit('select', this.project)
    },
    toggleExpand() {
      this.$emit('toggle-expand', this.project.project_name)
    }
  }
}
</script>
