```vue src/components/ProjectList.vue
<script setup>
import ProjectCard from './ProjectCard.vue'
</script>

<template>
  <div class="flex flex-col gap-0 flex-1 overflow-hidden h-full">
    <!-- Search Bar -->
    <div class="input input-bordered input-sm bg-base-200 flex items-center gap-2 flex-shrink-0 mx-4 my-3">
      <i class="fa-solid fa-magnifying-glass text-base-content/50"></i>
      <input
        v-model="searchQuery"
        type="text"
        placeholder="Search projects..."
        class="flex-1 bg-transparent outline-none text-sm"
      />
      <button
        v-if="searchQuery"
        @click="clearSearch"
        class="btn btn-ghost btn-xs btn-circle"
      >
        <i class="fa-solid fa-xmark"></i>
      </button>
      <div class="divider divider-horizontal m-0"></div>
      <!-- Project Count Badge -->
      <div class="badge badge-sm badge-ghost gap-1 flex-shrink-0">
        <i class="fa-solid fa-list text-xs"></i>
        <span>{{ visibleProjectCount }}</span>
      </div>
      <div class="divider divider-horizontal m-0"></div>
      <button
        @click="refreshProjects"
        class="btn btn-ghost btn-xs btn-circle tooltip"
        data-tip="Refresh"
      >
        <i class="fa-solid fa-arrows-rotate"></i>
      </button>
    </div>

    <!-- Projects List (scrollable) -->
    <div class="flex-1 overflow-y-auto overflow-x-hidden border-t border-base-300">
      <!-- List Items -->
      <div v-if="sortedFilteredProjects.length > 0" class="divide-y divide-base-300">
        <ProjectCard
          v-for="project in sortedFilteredProjects"
          :key="project.project_name"
          :project="project"
          :is-current="project.project_name === currentProject?.project_name"
          :is-expanded="isExpanded(project.project_name)"
          :current-project="currentProject"
          @select="onProjectSelect"
          @open-folder="$ui.coderOpenPath(project)"
          @toggle-expand="toggleExpand"
        />
      </div>

      <!-- Empty State -->
      <div v-else class="flex flex-col items-center justify-center gap-3 h-40 text-center text-base-content/50">
        <i class="fa-solid fa-inbox text-4xl"></i>
        <div>
          <p class="font-semibold">No projects found</p>
          <p class="text-xs">{{ searchQuery ? 'Try adjusting your search' : 'Start by adding a project' }}</p>
        </div>
      </div>
    </div>

    <!-- Footer Actions -->
    <div class="flex justify-end items-center gap-2 pt-3 px-4 pb-3 border-t border-base-300 flex-shrink-0">
      <button
        @click="$emit('open-new-project')"
        class="btn btn-primary btn-sm gap-2"
      >
        <i class="fa-solid fa-folder-plus"></i>
        New Project
      </button>
    </div>
  </div>
</template>

<script>
export default {
  props: {
    currentProject: Object
  },
  emits: ['select-project', 'open-new-project'],
  data() {
    return {
      searchQuery: '',
      allProjects: [],
      projectMap: {},
      expandedProjects: new Set()
    }
  },
  computed: {
    filteredProjects() {
      if (!this.searchQuery.trim()) {
        return this.allProjects
      }
      const query = this.searchQuery.toLowerCase()
      // Filter parents and children by search query
      return this.allProjects.filter(p => {
        const parentMatches = p.project_name.toLowerCase().includes(query) ||
          p.abs_project_path.toLowerCase().includes(query)

        const childMatches = p.childProjects?.some(child =>
          child.project_name.toLowerCase().includes(query) ||
          child.abs_project_path.toLowerCase().includes(query)
        )

        return parentMatches || childMatches
      })
    },
    sortedFilteredProjects() {
      return [...this.filteredProjects].sort((a, b) => {
        if (a.last_access_time && b.last_access_time) {
          return new Date(b.last_access_time) - new Date(a.last_access_time)
        }
        return a.project_name.localeCompare(b.project_name)
      })
    },
    visibleProjectCount() {
      return this.sortedFilteredProjects.length
    }
  },
  watch: {
    searchQuery(newQuery) {
      // Auto-expand all parents when searching
      if (newQuery.trim()) {
        this.expandedProjects.clear()
        this.sortedFilteredProjects.forEach(p => {
          if (p.childProjects?.length > 0) {
            this.expandedProjects.add(p.project_name)
          }
        })
      }
    }
  },
  mounted() {
    this.loadProjects()
  },
  methods: {
    loadProjects() {
      const projects = [
        ...this.$projects?.childProjects || [],
        ...this.$projects?.projectDependencies || [],
        ...this.$projects?.allParentProjects || []
      ]
      this.allProjects = projects.filter((p, i, a) =>
        a.findIndex(x => x.project_name === p.project_name) === i
      )
      this.allProjects.forEach(p => {
        this.projectMap[p.project_name] = p
      })
    },
    clearSearch() {
      this.searchQuery = ''
      this.expandedProjects.clear()
    },
    refreshProjects() {
      this.$projects?.loadAllProjects()
      this.loadProjects()
    },
    isExpanded(projectName) {
      return this.expandedProjects.has(projectName)
    },
    toggleExpand(projectName) {
      if (this.expandedProjects.has(projectName)) {
        this.expandedProjects.delete(projectName)
      } else {
        this.expandedProjects.add(projectName)
      }
    },
    onProjectSelect(project) {
      this.$emit('select-project', project)
    }
  }
}
</script>
```

---

## Design Breakdown

| **Dimension** | **Specification** |
|---|---|
| **Expand/Collapse Toggle** | Chevron icon (rotates 90° on expand), positioned left of icon; only visible for parents with children |
| **Child Count Badge** | Subtle `badge-ghost` showing count next to project name |
| **Child Rendering** | Indented row with left border indicator; lighter background tint; smaller typography hierarchy |
| **Search Behavior** | Auto-expands all parent projects; shows matching parents + children together |
| **Selection State** | Active badge on selected project; click anywhere on row to select |

---

## Anti-Patterns to Avoid

1. **Do NOT** hide the expand toggle when not hovered—children visibility should feel intentional, not hidden.
2. **Do NOT** collapse parents on search clear—let user control expansion state manually outside search mode.
3. **Do NOT** nest child selection handlers—use `@click.stop` on child action buttons to prevent event bubbling.

---

## Step-by-Step Implementation

1. **Replace ProjectCard.vue** with the new version (includes expand toggle + child rendering)
2. **Replace ProjectList.vue** with the new version (includes expand state management + smart search)
3. **Test expanding/collapsing** a parent project manually
4. **Test search** to confirm all parents auto-expand and filtered results display

The implementation is now complete! The parent-child hierarchy is fully functional with collapsible sections and smart search expansion.

# Implementation: Search Debouncing with Minimum Character Threshold

## Direct Recommendation
Add a debounce mechanism with a 300ms delay and enforce a minimum of 3 characters before filtering executes. This prevents unnecessary filter computations on every keystroke while maintaining responsive UX feedback.

---

## Updated Component

```vue src/components/ProjectList.vue
