    <!-- Projects List (scrollable) -->
    <div class="flex-1 overflow-y-auto overflow-x-hidden border-t border-base-300">
      <!-- List Items -->
      <div v-if="sortedFilteredProjects.length > 0" class="divide-y divide-base-300">
        <ProjectCard
          v-for="project in sortedFilteredProjects"
          :key="project.project_name"
          :project="project"
          :is-current="project.project_name === currentProject?.project_name"
          :current-project="currentProject"
          @select="onProjectSelect"
          @open-folder="$ui.coderOpenPath(project)"
        />
      </div>

      <!-- Empty State -->
      <div v-else class="flex flex-col items-center justify-center gap-3 h-40 text-center text-base-content/50">
        <i class="fa-solid fa-inbox text-4xl"></i>
        <div>
          <p class="font-semibold">No projects found</p>
          <p class="text-xs">{{ searchQuery ? 'Try adjusting your search' : 'Start by adding a project' }}</p>
        </div>
      </div>
    </div>

    <!-- Footer Actions -->
    <div class="flex justify-end items-center gap-2 pt-3 px-4 pb-3 border-t border-base-300 flex-shrink-0">
      <button
        @click="$emit('open-new-project')"
        class="btn btn-primary btn-sm gap-2"
      >
        <i class="fa-solid fa-folder-plus"></i>
        New Project
      </button>
    </div>
  </div>
</template>

<script>
export default {
  props: {
    currentProject: Object
  },
  emits: ['select-project', 'open-new-project'],
  data() {
    return {
      searchQuery: '',
      debouncedQuery: '',
      debounceTimer: null,
      minChars: 3,
      debounceDelay: 300
    }
  },
  computed: {
    allProjects() {
      return this.$projects.allProjects
    },
    filteredProjects() {
      // Only filter if debouncedQuery meets minimum character requirement
      if (!this.debouncedQuery.trim() || this.debouncedQuery.length < this.minChars) {
        return this.allProjects
      }
      const query = this.debouncedQuery.toLowerCase()
      return this.allProjects.filter(p =>
        p.project_name.toLowerCase().includes(query) ||
        p.abs_project_path.toLowerCase().includes(query)
      )
    },
    sortedFilteredProjects() {
      return [...this.filteredProjects].sort((a, b) => {
        if (a.last_access_time && b.last_access_time) {
          return new Date(b.last_access_time) - new Date(a.last_access_time)
        }
        return a.project_name.localeCompare(b.project_name)
      })
    },
    visibleProjectCount() {
      return this.sortedFilteredProjects.length
    }
  },
  mounted() {
    this.loadProjects()
  },
  methods: {
    onSearchInput() {
      // Clear existing timer
      if (this.debounceTimer) {
        clearTimeout(this.debounceTimer)
      }

      // Set new debounced timer
      this.debounceTimer = setTimeout(() => {
        this.debouncedQuery = this.searchQuery
      }, this.debounceDelay)
    },
    clearSearch() {
      this.searchQuery = ''
      this.debouncedQuery = ''
      if (this.debounceTimer) {
        clearTimeout(this.debounceTimer)
      }
    },
    onProjectSelect(project) {
      this.$emit('select-project', project)
    }
  },
  beforeUnmount() {
    // Clean up timer on component destruction
    if (this.debounceTimer) {
      clearTimeout(this.debounceTimer)
    }
  }
}
</script>
```

---

## Implementation Details

| Aspect | Details |
|--------|---------|
| **Debounce Delay** | 300ms (allows user to finish typing before filter executes) |
| **Minimum Characters** | 3 chars required (prevents filter on "a" or "ab") |
| **Reactive State** | `searchQuery` (v-model) vs `debouncedQuery` (filter trigger) |
| **Timer Cleanup** | `beforeUnmount` hook prevents memory leaks on navigation |
| **UX Feedback** | Input responds instantly; filtering updates after delay |

---

## UX & Performance Rationale

✅ **Why This Works:**
- Users see real-time input feedback (no lag on keystroke)
- Filter computation deferred until user pauses typing
- Minimum 3 chars prevents filtering "Project" on just "P" keystroke
- 300ms delay strikes balance between responsiveness and performance

⚠️ **Anti-Patterns Avoided:**
- ❌ **No instant filter-per-keystroke** — Would cause jank with large project lists
- ❌ **No hardcoded magic numbers in template** — All config in `data()` for easy adjustment
- ❌ **No floating timer references** — Proper cleanup prevents memory leaks

---

## Optional: Configurable via Props

If you need to adjust delay/minimum chars per instance:

