    }
  },
  data() {
    return {
      searchQuery: '',
      debouncedQuery: '',
      debounceTimer: null,
      minChars: this.minSearchChars,
      debounceDelay: this.debounceMs
    }
  }
  // ... rest remains the same
}
```

