      this.searchQuery = ''
      this.debouncedQuery = ''
      if (this.debounceTimer) {
        clearTimeout(this.debounceTimer)
      }
    },
    onProjectSelect(project) {
      this.$emit('select-project', project)
    }
  },
  beforeUnmount() {
    if (this.debounceTimer) {
      clearTimeout(this.debounceTimer)
    }
  }
}
